INSERT INTO usuarios_admin (nome, email, senha_hash) SELECT 'Administrador', 'admin@robson.dev', '{bcrypt}$2a$10$REPLACE_WITH_A_BCRYPT_HASH' WHERE NOT EXISTS (SELECT 1 FROM usuarios_admin WHERE email = 'admin@robson.dev');
